 * along only when present (an in_progress stamp carries neither).
 */
function buildCheckRunBody(o) {
    var body = {
        name: String(o.name),
        head_sha: String(o.headSha),
        status: String(o.status),
        output: {
            title: String(o.title),
            summary: truncateCheckRunSummary(o.summary)
