    SUMMARY_CHAR_LIMIT: SUMMARY_CHAR_LIMIT,
    SUMMARY_TRUNCATION_MARKER: SUMMARY_TRUNCATION_MARKER,
    truncateCheckRunSummary: truncateCheckRunSummary,
