const fs=require('fs');
const base=require('/tmp/base/crap-baseline.json');
const txt=fs.readFileSync('/tmp/crap-all.txt','utf8').split('\n');
// rows: Method<spaces>File<spaces>CC Cov% CRAP  — parse from the right
const cur={};
for(const l of txt.slice(3)){
  if(!l.trim()) continue;
  const parts=l.trim().split(/\s+/);
  if(parts.length<5) continue;
  const crap=parseFloat(parts[parts.length-1]);
  const cc=parseInt(parts[parts.length-3],10);
  const file=parts[parts.length-4];
  if(isNaN(crap)||isNaN(cc)||!/\.(js|cjs|mjs)$/.test(file)) continue;
  const name=parts.slice(0,parts.length-4).join(' ');
  cur[file+'::'+name]={cc,crap};
}
console.log('parsed current fns:', Object.keys(cur).length);
const baseKeys=Object.keys(base.functions);
const curKeys=new Set(Object.keys(cur));
const missing=baseKeys.filter(k=>!curKeys.has(k));
console.log('baseline keys NOT in current:', missing.length,'/',baseKeys.length);
console.log('missing sample:', missing.slice(0,6));
""}

