  const COMPLEX=new Set(['IfStatement','ForStatement','ForInStatement','ForOfStatement','WhileStatement','DoWhileStatement','CatchClause','SwitchCase','ConditionalExpression']);
  const SKIP=new Set(['type','loc','range','sourceType','start','end','leadingComments','trailingComments','innerComments','extra','directives']);
