// One flow-break increment per structural node (basic + nesting), one per
// `&&`/`||` sequence root; then descend.
function cognitiveStep(s, n, depth, seqOp, visit) {
  if (COGNITIVE_TYPES.has(n.type)) {
    structuralStep(s, n, depth, visit);
    return;
